// The Hybrid UI theme layer (behavior per ADR-0004, ticket 04): the studio has three theme
// preferences - dark (the default), light, and follow-system. The choice persists under
// 'astra.theme', is written to the document as the data-theme attribute, and is applied before
// the first paint by the inline script in index.html (no flash of the wrong theme). The palette
// itself lives in tokens: :root carries dark, html[data-theme=light] the light map
// (generated by scripts/ui/palette-tokens.mjs). Plain functions here, DOM wiring in App/main.
export const THEME_PREFS = ['dark', 'light', 'system'];
export const THEME_KEY = 'astra.theme';
const DEFAULT_PREF = 'dark';

export function readThemePref(storage = globalThis.localStorage) {
  try {
    const v = storage?.getItem(THEME_KEY);
    return THEME_PREFS.includes(v) ? v : DEFAULT_PREF;
  } catch { return DEFAULT_PREF; }
}

export function saveThemePref(pref, storage = globalThis.localStorage) {
  try { storage?.setItem(THEME_KEY, pref); } catch { /* private mode: the choice lives for the session only */ }
}

// Which of the two real themes a preference means right now (systemPrefersDark comes from
// matchMedia('(prefers-color-scheme: dark)')).
export function resolveTheme(pref, systemPrefersDark) {
  if (pref === 'system') return systemPrefersDark ? 'dark' : 'light';
  return pref === 'light' ? 'light' : 'dark';
}

export function applyTheme(doc, resolved) {
  doc.documentElement.setAttribute('data-theme', resolved);
  const meta = doc.querySelector('meta[name=theme-color]');
  if (meta) meta.setAttribute('content', resolved === 'light' ? '#edefe7' : '#131719');
}
